<template>
  <view class="scheme-edit-page">
    <!-- 顶部导航：保留原有 -->
    <CustomHeader 
      title="方案编辑" 
      :showBack="true" 
      :showIcon="false" 
      @back-click="handleBack" 
    />

    <!-- 中间内容区：修改为index页面的样式结构 -->
    <view class="content-wrap">
      <scroll-view class="match-scroll" scroll-y>
        <view class="match-list">
          <view v-for="(item, index) in selectedMatchList" :key="index" class="match-row">
            <view class="match-category">
              <view class="league-name">{{ item.league_name }}</view>
              <view class="league-name" style="display: flex;justify-content: flex-start;width: 100%;">
                <text class="single"></text>{{ item.serial_number }}</view>
              <view class="match-time">{{ item.race_date }}</view>
            </view>
            <view class="match-cells">
              <view class="match-cell home" :class="{ selected: item.homeSelected }">
                <view class="team-name">{{ item.home_name }}</view>
                <text class="odds" v-if="item.win_multiplier">主胜{{ item.win_multiplier }}</text>
                <text class="odds rate"  v-if="item.home_win_rate"
                  >胜率{{ item.home_win_rate || '' }} <text style="margin-left: 10rpx; color: red">{{ item.homeHandicap || '' }}</text></text
                >
              </view>
              <view class="match-cell vs" :class="{ selected: item.vsSelected }">
                <text class="vs-text">VS</text>
                <text class="vs-odds" v-if="item.draw_multiplier">平{{ item.draw_multiplier }}</text>
              </view>
              <view class="match-cell away" :class="{ selected: item.awaySelected }">
                <text class="team-name">{{ item.visiting_name }}</text>
                <text class="odds" v-if="item.loss_multiplier">客胜{{ item.loss_multiplier }}</text>
                <text class="odds rate" v-if="item.visiting_win_rate"
                  >胜率{{ item.visiting_win_rate || '' }}<text style="margin-left: 10rpx; color: red">{{ item.visitingHandicap || '' }}</text></text
                >
              </view>
            </view>
          </view>

          <view class="empty-tip" v-if="selectedMatchList.length === 0">
            暂无已选赛事
          </view>
        </view>
      </scroll-view>
    </view>

    <!-- 底部投注栏：保留原有逻辑 -->
    <view class="bet-bar">
      <view class="bet-bar-top">
        <view class="collapse-area">
          <view class="multi-group">
            <text class="multi-label">投</text>
            <button class="multi-btn minus" @click="handleMinus">-</button>
            <input class="multi-input" type="number" v-model.number="betCount" min="1" inputmode="numeric" />
            <button class="multi-btn plus" @click="handlePlus">+</button>
            <text class="multi-unit">倍</text>
          </view>
        </view>
      </view>
      <view class="bet-bar-bottom">
        <view class="bottom-middle">
          <text class="select-tip">{{ selectedMatchCount === 0 ? "请选择比赛" : `已选${selectedMatchCount}场` }}</text>
          <text class="bonus-tip">预计:  然后根据这个公司计算一下    后面再加上 仅供参考以彩票奖金为主</text>
        </view>
        <view class="bottom-right">
          <button class="confirm-btn" :disabled="selectedMatchCount === 0 || isPayLoading" @click="handleConfirmBet">
            {{ isPayLoading ? "支付中..." : "确认投注" }}
          </button>
        </view>
      </view>
    </view>
  </view>
</template>

<script>
import CustomHeader from "@/components/CustomHeader.vue";
import { formatTimeToMDWeekHM } from "@/utils/data"; // 替换为index页面的时间格式化方法

export default {
  components: { CustomHeader },
  data() {
    return {
      selectedMatchList: [],
      betCount: 1,
      isPayLoading: false
    };
  },
  computed: {
    selectedMatchCount() {
      return this.selectedMatchList.filter(item => {
        return item.homeSelected || item.vsSelected || item.awaySelected;
      }).length;
    },
    totalBetAmount() {
      return this.betCount * 2;
    }
  },
  onShow() {
    uni.setTabBarStyle({ height: '0px' });
  },
  onLoad() {
    const eventChannel = this.getOpenerEventChannel();
    if (eventChannel) {
      eventChannel.on("selectedData", (data) => {
        this.selectedMatchList = data.matches || [];
        this.betCount = data.betCount || 1;
      });
    }
  },
  onUnload() {
    const editedData = {
      matches: this.selectedMatchList,
      betCount: this.betCount
    };
    uni.setStorageSync("editedMatchData", JSON.stringify(editedData));
  },
  methods: {
    // 使用index页面的时间格式化方法
    formDate(time) {
      return formatTimeToMDWeekHM(time);
    },
    toggleSelect(item, key) {
      if (item.is_discontinued === 1) return;
      this.$set(item, key, !item[key]);
    },
    handleBack() {
      this.saveEditedData();
      uni.navigateBack({ delta: 1 });
    },
    handleGotoHome() {
      this.saveEditedData();
      uni.navigateBack({ delta: 1 });
    },
    saveEditedData() {
      const deepCopyData = JSON.parse(JSON.stringify({
        matches: this.selectedMatchList,
        betCount: this.betCount
      }));
      uni.setStorageSync("editedMatchData", JSON.stringify(deepCopyData));
    },
    handleDeleteMatch(index) {
      this.selectedMatchList.splice(index, 1);
    },
    handleClearAll() {
      this.selectedMatchList = [];
    },
    handleMinus() {
      if (this.betCount > 1) this.betCount--;
    },
    handlePlus() {
      this.betCount++;
    },
    handleConfirmBet() {
      if (this.selectedMatchCount === 0) {
        uni.showToast({ title: "请先选择至少一场赛事的投注选项", icon: "none", duration: 1500 });
        return;
      }

      this.isPayLoading = true;

      const payRequestData = {
        selectedMatches: this.selectedMatchList.map(item => ({
          matchId: item.id,
          selectType: item.homeSelected ? "home_win" : item.vsSelected ? "draw" : "away_win",
          handicap: item.homeHandicap || item.visitingHandicap || "",
          odds: item.homeSelected ? item.win_multiplier : item.vsSelected ? item.draw_multiplier : item.loss_multiplier
        })),
        betCount: this.betCount,
        totalAmount: this.totalBetAmount,
        payWay: "wechat"
      };

      uni.request({
        url: "https://你的域名/你的wxPay接口路径",
        method: "POST",
        header: {
          "Content-Type": "application/json",
          "token": uni.getStorageSync("userToken")
        },
        data: payRequestData,
        success: (res) => {
          const { code, data, message } = res.data;

          if (code === 200 && data.wechatPayParams) {
            this.invokeWxPayment(data.wechatPayParams);
          } else {
            this.isPayLoading = false;
            uni.showToast({ title: message || "获取支付信息失败", icon: "none", duration: 1500 });
          }
        },
        fail: (err) => {
          this.isPayLoading = false;
          uni.showToast({ title: "网络异常，请稍后重试", icon: "none", duration: 1500 });
          console.error("wxPay接口请求失败：", err);
        }
      });
    },
    invokeWxPayment(payParams) {
      const { timeStamp, nonceStr, package: prepayPackage, signType, paySign, orderId } = payParams;

      uni.requestPayment({
        provider: "wxpay",
        timeStamp: timeStamp + "",
        nonceStr: nonceStr,
        package: prepayPackage,
        signType: signType,
        paySign: paySign,
        success: (res) => {
          this.isPayLoading = false;
          uni.showToast({ title: "支付成功", icon: "success", duration: 1500 });
          setTimeout(() => {
            uni.navigateTo({ url: `/pages/orderDetail/orderDetail?orderId=${orderId}` });
            this.selectedMatchList = [];
            this.betCount = 1;
          }, 1500);
        },
        fail: (err) => {
          this.isPayLoading = false;
          if (err.errMsg.includes("cancel")) {
            uni.showToast({ title: "已取消支付", icon: "none", duration: 1500 });
          } else {
            uni.showToast({ title: "支付失败，请重试", icon: "none", duration: 1500 });
            console.error("微信支付失败：", err);
          }
        },
        complete: () => {
          this.isPayLoading = false;
        }
      });
    }
  }
};
</script>

<style scoped lang="scss">
.scheme-edit-page {
  background-color: #f5f5f5;
  box-sizing: border-box;
  height: 100vh;
  margin: 0;
  padding: 0;
}

::v-deep .custom-header {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  z-index: 10 !important;
}

.content-wrap {
  height: calc(100vh - 90rpx);
  overflow: hidden;
}

.match-scroll {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  overflow-y: auto;

  .match-list {
    overflow: hidden;
    padding-top: 90rpx;

    .match-row {
      display: flex;
      background-color: #fff;
      border-bottom: 1rpx solid #3cb371;
      padding: 8rpx 20rpx 8rpx 20rpx;

      .match-category {
        width: 180rpx;
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: center;
        text-align: center;

        .league-name {
          font-size: 24rpx;
          color: #777;
          margin-bottom: 6rpx;
          .single{
            display: inline-block;
            box-sizing: border-box;
            padding-left: 6rpx;
            width: 40rpx;
            color: #fff;
            text-align: left;
            border-top-right-radius: 15rpx;
            border-bottom-right-radius: 16rpx;
            margin-right: 10rpx;
          }
        }

        .match-time {
          font-size: 22rpx;
          color: #999;
        }
      }

      .match-cells {
        flex: 1;
        display: flex;
        border: 1rpx solid #66cdaa;
        border-radius: 8rpx;
        overflow: hidden;

        .match-cell {
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          padding: 16rpx 10rpx;
          cursor: pointer;
          transition: background-color 0.2s;

          &.home {
            width: 40%;
            border-right: 1rpx solid #eee;
          }

          &.vs {
            width: 16%;
            flex-direction: column;
            gap: 4rpx;

            .vs-text {
              font-size: 24rpx;
              font-weight: 400;
              color: #333;
              margin-bottom: 0;
            }
            .vs-odds {
              font-weight: 400;
              font-size: 24rpx;
              color: #999;
            }
          }
          &.away {
            width: 40%;
            border-left: 1rpx solid #eee;
          }

          &.selected {
            background-color: #d92929;
            color: #fff;
            .vs-text,
            .team-name,
            .vs-odds,
            .odds {
              color: #fff !important;
            }
          }

          .team-name {
            font-size: 24rpx;
            color: #666;
            margin-bottom: 8rpx;
            font-weight: 400;
            text-align: center;
            width: 100%;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
          }

          .odds {
            font-size: 24rpx;
            color: #999;
            margin-bottom: 4rpx;

            &.rate {
              color: #999;
              font-size: 22rpx;
            }
          }
        }
      }
    }

    .empty-tip {
      text-align: center;
      padding: 50rpx 0;
      font-size: 26rpx;
      color: #999;
      background-color: #fff;
      border-top: 1rpx solid #f2f2f2;
    }
  }
}

.bet-bar {
  position: fixed !important;
  width: 100% !important;
  bottom: 0rpx !important;
  left: 0 !important;
  z-index: 10 !important;
  background-color: #fff;
  box-shadow: 0 -2rpx 10rpx rgba(0, 0, 0, 0.1);
  padding-bottom: 0 !important;
  height: 180rpx;

  .bet-bar-top {
    .collapse-area {
      display: flex;
      align-items: center;
      justify-content: space-around;
      height: 80rpx;
      box-sizing: border-box;
      padding: 10rpx 20rpx;
      border-bottom: 2rpx solid #eee;

      .multi-group {
        display: flex;
        align-items: center;
        gap: 10rpx;

        .multi-label {
          height: 100%;
          font-size: 30rpx;
          color: #333;
        }

        .multi-btn {
          width: 52rpx;
          height: 52rpx;
          background-color: #ddd;
          color: #333;
          font-size: 32rpx;
          display: flex;
          align-items: center;
          justify-content: center;
          border: 1rpx solid #ccc;
          padding: 0;
          margin: 0;
          border-radius: 0;
        }

        .multi-input {
          width: 180rpx;
          height: 52rpx;
          background-color: #fff;
          color: #333;
          text-align: center;
          font-size: 30rpx;
          border: 1rpx solid #ccc;
          padding: 0;
          box-sizing: border-box;
          border-radius: 0;
        }
      }
    .bottom-right {
      width: 200rpx;

      .confirm-btn {
        width: 100%;
        height: 76rpx;
        background-color: #d92929;
        color: #fff;
        border-radius: 8rpx;
        font-size: 28rpx;
        border: none;
        margin: 0;
        display: flex;
        align-items: center;
        justify-content: center;

        &[disabled] {
          background-color: #666;
          color: #aaa;
          cursor: not-allowed;
        }
      }
    }
    }
    
  }

  .bet-bar-bottom {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 20rpx;
    height: 100rpx;

    .bottom-middle {
      text-align: center;

      .select-tip {
        font-size: 28rpx;
        color: #333;
        margin-bottom: 4rpx;
      }

      .bonus-tip {
        font-size: 20rpx;
        color: #999;
      }
    }

    .bottom-right {
      width: 200rpx;

      .confirm-btn {
        width: 100%;
        height: 76rpx;
        background-color: #d92929;
        color: #fff;
        border-radius: 8rpx;
        font-size: 28rpx;
        border: none;
        margin: 0;
      }
    }
  }
}

::-webkit-scrollbar {
  display: none;
}
</style>